import { test, expect } from '@playwright/test';

test.describe('Product Sorting by Price', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://www.saucedemo.com/');
  });

  test('should sort products by price in ascending order when selecting "lohi"', async ({ page }) => {
    // Login with standard user
    const usernameInput = page.getByLabel('Username');
    const passwordInput = page.getByLabel('Password');
    const loginButton = page.getByRole('button', { name: /login/i });

    await usernameInput.fill('standard_user');
    await passwordInput.fill('secret_sauce');
    await loginButton.click();

    // Wait for inventory page to load
    await page.waitForURL('https://www.saucedemo.com/inventory.');

    // Verify products are visible
    const productItems = page.locator('[data-testid="inventory-item"]');
    await expect(productItems).toHaveCount(6);

    // Get initial prices to verify sorting later
    const initialPrices = await page.locator('[data-testid="inventory-item-price"]').allTextContents();
    const initialPriceNumbers = initialPrices.map(price => parseFloat(price.replace('$', '')));

    // Select "lohi" option from sort dropdown
    const sortDropdown = page.getByLabel('Sort by');
    await sortDropdown.selectOption({ value: 'lohi' });

    // Wait for sorting to complete
    await page.waitForTimeout(500);

    // Verify products are reordered
    const sortedPrices = await page.locator('[data-testid="inventory-item-price"]').allTextContents();
    const sortedPriceNumbers = sortedPrices.map(price => parseFloat(price.replace('$', '')));

    // Verify prices are in ascending order
    for (let i = 0; i < sortedPriceNumbers.length - 1; i++) {
      expect(sortedPriceNumbers[i]).toBeLessThanOrEqual(sortedPriceNumbers[i + 1]);
    }

    // Verify the first item is the cheapest
    expect(sortedPriceNumbers[0]).toBe(19.99);
  });

  test('should handle edge case when sorting with multiple items having the same price', async ({ page }) => {
    // Login with standard user
    const usernameInput = page.getByLabel('Username');
    const passwordInput = page.getByLabel('Password');
    const loginButton = page.getByRole('button', { name: /login/i });

    await usernameInput.fill('standard_user');
    await passwordInput.fill('secret_sauce');
    await loginButton.click();

    // Wait for inventory page to load
    await page.waitForURL('https://www.saucedemo.com/inventory.');

    // Verify products are visible
    const productItems = page.locator('[data-testid="inventory-item"]');
    await expect(productItems).toHaveCount(6);

    // Select "lohi" option from sort dropdown
    const sortDropdown = page.getByLabel('Sort by');
    await sortDropdown.selectOption({ value: 'lohi' });

    // Wait for sorting to complete
    await page.waitForTimeout(500);

    // Verify all prices are in ascending order
    const sortedPrices = await page.locator('[data-testid="inventory-item-price"]').allTextContents();
    const sortedPriceNumbers = sortedPrices.map(price => parseFloat(price.replace('$', '')));

    for (let i = 0; i < sortedPriceNumbers.length - 1; i++) {
      expect(sortedPriceNumbers[i]).toBeLessThanOrEqual(sortedPriceNumbers[i + 1]);
    }

    // Verify the last item is the most expensive
    expect(sortedPriceNumbers[sortedPriceNumbers.length - 1]).toBe(100);

    // Verify the sort indicator is visible
    const sortIndicator = page.getByText('Price: low to high');
    await expect(sortIndicator).toBeVisible();
  });
});
